INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Zeigt ipconfig nur IPv6-Adressen an?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IPv4 und mehr"}, {"text": "Ja", "correct": false, "because": "Nicht auf IPv6 beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information liefert ipconfig über IPv6?', 3, '[{"text": "Link-Local-Adresse", "correct": true, "because": "Standard für IPv6"}, {"text": "Portnummern", "correct": false, "because": "Transportebene"}, {"text": "Paketverlust", "correct": false, "because": "Ping-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Details zeigt ipconfig für Netzwerke?', 5, '[{"text": "IPv6-Adresse", "correct": true, "because": "Zeigt aktuelle Adresse"}, {"text": "Standardgateway", "correct": true, "because": "Routing-Info"}, {"text": "Latenzzeit", "correct": false, "because": "Ping-Aufgabe"}, {"text": "Bandbreitenlimit", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ipconfig zeigt die IPv6-Adresse an. b) Es ist nur für Windows.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Linux nutzt ifconfig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei ipconfig für IPv6?', 4, '[{"text": "Link-Local-Adresse", "correct": false, "because": "Wichtige Info"}, {"text": "Subnetzpräfix", "correct": false, "because": "Teil der Konfiguration"}, {"text": "CPU-Auslastung", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ipconfig den Scope anzeigt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Adressen, kein Scope"}, {"text": "Ja", "correct": false, "because": "Scope nicht explizit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse finde ich mit ipconfig?', 3, '[{"text": "FE80:: mit Interface", "correct": true, "because": "Link-Local IPv6"}, {"text": "FF02::1", "correct": false, "because": "Multicast, nicht eigener"}, {"text": "127.0.0.1", "correct": false, "because": "IPv4 Loopback"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche IPv6-Infos liefert ipconfig?', 5, '[{"text": "Temporäre Adresse", "correct": true, "because": "Für Privatsphäre"}, {"text": "Gateway-Adresse", "correct": true, "because": "Routing-Info"}, {"text": "Paketverlust", "correct": false, "because": "Ping-spezifisch"}, {"text": "DNS-Status", "correct": false, "because": "Nur Server-Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ipconfig zeigt IPv6-Adressen. b) Es misst Latenz. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Latenz ist Ping"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ipconfig?', 4, '[{"text": "Netzwerkadapter", "correct": false, "because": "Zeigt Konfiguration"}, {"text": "IPv6-Unterstützung", "correct": false, "because": "Für IPv6-Adressen"}, {"text": "Webserver", "correct": true, "because": "Nicht Netzwerk-Tool"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ipconfig globale IPv6-Adressen?', 2, '[{"text": "Ja", "correct": true, "because": "Falls zugewiesen"}, {"text": "Nein", "correct": false, "because": "Abhängig von Konfiguration"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option hilft mir, alle IPv6-Details zu sehen?', 4, '[{"text": "ipconfig /all", "correct": true, "because": "Vollständige Info"}, {"text": "ipconfig /renew", "correct": false, "because": "Aktualisiert nur"}, {"text": "ipconfig /flushdns", "correct": false, "because": "DNS-Cache"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ipconfig nur IPv4 zeigt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IPv6 wird angezeigt"}, {"text": "Ja", "correct": false, "because": "Missverständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei ipconfig für IPv6?', 3, '[{"text": "Link-Local-Adresse", "correct": true, "because": "Immer vorhanden"}, {"text": "DNS-Server", "correct": false, "because": "Sekundär"}, {"text": "Bandbreite", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ipconfig zeigt das Gateway. b) Es ist ein Linux-Tool.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Windows-spezifisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ipconfig für IPv6?', 5, '[{"text": "Adressübersicht", "correct": true, "because": "Zeigt IPv6-Konfig"}, {"text": "Gateway-Info", "correct": true, "because": "Routing sichtbar"}, {"text": "Latenzmessung", "correct": false, "because": "Ping-Aufgabe"}, {"text": "Paketanalyse", "correct": false, "because": "Andere Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei ipconfig für IPv6 unwichtig?', 3, '[{"text": "IPv6-Adresse", "correct": false, "because": "Kerninformation"}, {"text": "Adaptername", "correct": false, "because": "Identifiziert Schnittstelle"}, {"text": "CPU-Takt", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ipconfig temporäre IPv6-Adressen?', 3, '[{"text": "Ja", "correct": true, "because": "Falls aktiviert"}, {"text": "Nein", "correct": false, "because": "Abhängig von Konfig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ipconfig den DNS-Server anzeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Teil der Netzwerkinfo"}, {"text": "Nein", "correct": false, "because": "Mit /all sichtbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eingabe zeigt mir die volle IPv6-Konfiguration?', 4, '[{"text": "ipconfig /all", "correct": true, "because": "Alle Details"}, {"text": "ipconfig /release", "correct": false, "because": "Gibt Adresse frei"}, {"text": "ipconfig /displaydns", "correct": false, "because": "Nur DNS-Cache"}]');
